{
  "vulnerable_symbols": [
    "axios",
    "axios.request"
  ],
  "trigger": "应用使用 axios 的 Node HTTP adapter 发起请求，设置 responseType: 'stream' 和 maxContentLength，并读取来自不可信服务器的大响应。",
  "preconditions": [
    "运行在 Node.js 且使用 HTTP adapter（adapter: 'http' 或默认）",
    "请求配置 responseType: 'stream'",
    "请求配置了 maxContentLength 并依赖其限制响应大小",
    "应用读取或消费返回的响应流",
    "响应来自不可信或攻击者可控的 HTTP 服务器，可返回超过 maxContentLength 的大响应"
  ],
  "exploit_evidence": [
    {
      "src": 4,
      "kind": "poc",
      "quote": "Start an HTTP server that returns a 2 MiB response body."
    },
    {
      "src": 2,
      "kind": "poc",
      "quote": "SSVC Exploitation: poc"
    }
  ],
  "fixed_version": "1.15.1",
  "summary_zh": "axios 1.7.4 流式响应绕过 maxContentLength，可致 DoS，请升级 1.15.1。"
}
